import React, { useRef, useState } from "react";
import styled from "styled-components";
import { apiCreateSample } from "../service/sample";
import {apiGetVirulenceInfo} from "../service/virulence"
import { apiGetAmrInfo } from "../service/amr";
import Result from "../components/Result";

const Container = styled.div`
  margin-top: 10px;
  display: flex;
  justify-content: center;
`;

const Wrapper = styled.div`
  width: 90%;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const Title = styled.h2`
  margin-bottom: 20px;
  text-align: center;
  font-size: 40px;
  font-weight: bold;
`;

const DropdownWrapper = styled.div`
  margin-top: 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 100%;
`;

const Dropdown = styled.select`
  padding: 10px;
  border-radius: 5px;
  border: 1px solid #dee2e6;
  font-size: 16px;
  width: 100%;
  &:focus {
    outline: none;
    border: 1px solid #86b7fe;
    box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
  }
`;

const InputWrapper = styled.div`
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 100%;
`;

const Input = styled.input`
  padding: 10px;
  border-radius: 5px;
  border: 1px solid #dee2e6;
  font-size: 16px;
  &:focus {
    outline: none;
    border: 1px solid #86b7fe;
    box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
  }
`;

const ChooseFileButtonWrapper = styled.div`
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
`;

const ChooseFileButton = styled.label`
  padding: 8px 12px;
  background-color: #007bff;
  color: white;
  border-radius: 5px;
  cursor: pointer;
  display: inline-block;
  font-size: 16px;
  text-align: center;
  transition: background-color 0.3s;

  &:hover {
    background-color: #0056b3;
  }

  input {
    display: none;
  }
`;

const UploadIcon = styled.span`
  display: inline-block;
  width: 20px;
  height: 20px;
  background-color: white;
  clip-path: polygon(100% 50%, 0 100%, 100% 100%);
  margin-right: 8px;
  transform: rotate(45deg);
`;

const FileName = styled.p`
  font-size: 16px;
  color: #333;
  margin: 0;
`;

const ButtonWrapper = styled.div`
  display: flex;
  justify-content: center;
  margin-top: 20px;
`;

const ButtonSubmit = styled.button`
  padding: 12px 20px;
  background-color: #007bff;
  color: white;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 18px;
  transition: background-color 0.3s;

  &:hover {
    background-color: #0056b3;
  }
`;

const Submit = () => {
  const [selectedExperiment, setSelectedExperiment] = useState("");
  const [sampleName, setSampleName] = useState("");
  const [file, setFile] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const fileInputRef = useRef(null);
  const [fastaInfo, setFastaInfo]= useState(
    {
    name: "Sample1",
    header: ">Sample1_header",
    length: 12345,
    createdAt: "2025-04-01T14:30:00Z"
    }
  );
  const [virulenceInfo, setVirulenceInfo]=useState(
    [
      {
        sequence: "ATCGATCGATCG",
        gene: "Gene1",
        start: 100,
        stop: 200,
        strand: "+",
        identity: 98.5,
        coverage: 85.2,
        accession: "NC_12345",
        product: "Protein A"
      },
      {
        sequence: "GCTAGCTAGCTA",
        gene: "Gene2",
        start: 250,
        stop: 350,
        strand: "-",
        identity: 95.7,
        coverage: 80.4,
        accession: "NC_67890",
        product: "Protein B"
      }
    ]   
  );
  const [amrInfo, setAmrInfo] = useState();
  const handleFileChange = (e) => {
    if (e.target.files[0]) {
      const uploadedFile = e.target.files[0];
      setFile(uploadedFile);
    }
  };

  const handleExperimentChange = (e) => {
    setSelectedExperiment(e.target.value);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!file || !sampleName || !selectedExperiment) {
      alert("Please complete all fields.");
      return;
    }

    setIsLoading(true);
    try {
      // API call for creating a sample (mocked here)
      await apiCreateSample({ name: sampleName, experimentId: selectedExperiment, file });
      alert("Sample submitted successfully!");
    } catch (error) {
      console.error("Error submitting sample:", error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Container>
      <Wrapper>
        <Title>Thêm mẫu thí nghiệm</Title>
        <DropdownWrapper>
          <Dropdown value={selectedExperiment} onChange={handleExperimentChange}>
            <option value="">Chọn thí nghiệm</option>
            <option value="1">Thí nghiệm 1</option>
            <option value="2">Thí nghiệm 2</option>
            <option value="3">Thí nghiệm 3</option>
          </Dropdown>
          <InputWrapper>
            <Input
              type="text"
              value={sampleName}
              onChange={(e) => setSampleName(e.target.value)}
              placeholder="Tên mẫu thí nghiệm"
            />
            <ChooseFileButtonWrapper>
              <ChooseFileButton>
                <UploadIcon />
                Chọn tệp FASTA
                <input
                  type="file"
                  accept=".fa, .fas, .fna, .fasta"
                  onChange={handleFileChange}
                  ref={fileInputRef}
                />
              </ChooseFileButton>
              {file && <FileName>{file.name}</FileName>}
            </ChooseFileButtonWrapper>
          </InputWrapper>
        </DropdownWrapper>
        <ButtonWrapper>
          <ButtonSubmit type="button" onClick={handleSubmit}>
            Submit
          </ButtonSubmit>
        </ButtonWrapper>
        <Result fastaInfo={fastaInfo} virulenceInfo={virulenceInfo} amrInfo={amrInfo}/>
      </Wrapper>
    </Container>
  );
};

export default Submit;
